    id: '79', slug: 'back-to-the-future', title: 'Back to the Future', title_ar: 'العودة إلى المستقبل', year: 1985,
    director: 'Robert Zemeckis', director_ar: 'Robert Zemeckis',
    cast: ['Michael J. Fox', 'Christopher Lloyd', 'Crispin Glover', 'Lea Thompson', 'Claudia Wells', 'Thomas F. Wilson'],
