    id: '168', slug: 'the-invisible-guest', title: 'The Invisible Guest', title_ar: 'الضيف الخفي', year: 2017,
    director: 'Oriol Paulo', director_ar: 'Oriol Paulo',
    cast: ['Mario Casas', 'Ana Wagener', 'Jose Coronado', 'Bárbara Lennie', 'Francesc Orella', 'Paco Tous'],
