    director: 'Vince Marcello', director_ar: 'Vince Marcello',
    cast: ['Joey King', 'Jacob Elordi', 'Joel Courtney', 'Molly Ringwald', 'Taylor Zakhar Perez', 'Maisie Richardson-Sellers'],
