    id: '636', slug: 'godzilla-minus-one', title: 'Godzilla Minus One', title_ar: 'Godzilla Minus One', year: 2023,
    director: 'Takashi Yamazaki', director_ar: 'Takashi Yamazaki',
    cast: ['Ryunosuke Kamiki', 'Minami Hamabe', 'Yuki Yamada', 'Munetaka Aoki', 'Hidetaka Yoshioka', 'Sakura Ando'],
    genres: ['scifi', 'horror', 'action'],
    poster_url: 'https://image.tmdb.org/t/p/w500/2E2WTX0TJEflAged6kzErwqX1kt.jpg',
