    id: '902', slug: 'greyhound', title: 'Greyhound', title_ar: 'Greyhound', year: 2020,
    director: 'Aaron Schneider', director_ar: 'Aaron Schneider',
    cast: ['Tom Hanks', 'Stephen Graham', 'Rob Morgan', 'Josh Wiggins', 'Tom Brittney', 'Elisabeth Shue'],
    genres: ['history', 'action', 'drama'],
    poster_url: 'https://image.tmdb.org/t/p/w500/kjMbDciooTbJPofVXgAoFjfX8Of.jpg',
