    director: 'Patrice Leconte', director_ar: 'Patrice Leconte',
    cast: ['Thierry Lhermitte', 'Michel Blanc', 'Christian Clavier', 'Gérard Jugnot', 'Josiane Balasko', 'Dominique Lavanant'],
    genres: ['comedy'],
    poster_url: 'https://image.tmdb.org/t/p/w500/tEiNHF6SqfguCKBdxwukrK10KbH.jpg',
