    id: '1039', slug: 'ghost-dog-the-way-of-the-samurai', title: 'Ghost Dog: The Way of the Samurai', title_ar: 'Ghost Dog: The Way of the Samurai', year: 1999,
    director: 'Jim Jarmusch', director_ar: 'Jim Jarmusch',
    cast: ['Forest Whitaker', 'John Tormey', 'Cliff Gorman', 'Frank Minucci', 'Richard Portnow', 'Tricia Vessey'],
    genres: ['crime', 'drama'],
    poster_url: 'https://image.tmdb.org/t/p/w500/gjcl07r9zgQ9tVo9alyHmysPFfX.jpg',
    backdrop_url: 'https://image.tmdb.org/t/p/original/9oRbHgbJf1Zr2fct8jBIKadpKya.jpg',
    trailer_url: 'https://www.youtube.com/watch?v=ZhR6jWWpUj0',
    description_ar: 'A Black hitman who models after the samurai of old finds himself targeted for death by the mob.',
