    id: '1253', slug: 'peaky-blinders-the-immortal-man', title: 'Peaky Blinders: The Immortal Man', title_ar: 'بيكي بلايندرز: الرجل الخالد', year: 2026,
    director: 'Tom Harper', director_ar: 'Tom Harper',
    cast: ['Cillian Murphy', 'Barry Keoghan', 'Rebecca Ferguson', 'Tim Roth', 'Stephen Graham', 'Sophie Rundle'],
