    reviews_count: 2449, is_featured: false, release_date: '2013-12-12', tags: ['drama', 'romance', 'fantasy', '2013', 'jarmusch'],
    pros_ar: ['عمق درامي استثنائي', 'أداء تمثيلي رائع', 'قصة إنسانية مؤثرة'],
