    director: 'Gilles Lellouche', director_ar: 'Gilles Lellouche',
    cast: ['Adèle Exarchopoulos', 'François Civil', 'Mallory Wanecque', 'Malik Frikah', 'Alain Chabat', 'Benoît Poelvoorde'],
    genres: ['romance', 'crime', 'drama'],
    poster_url: 'https://image.tmdb.org/t/p/w500/yu9dRyKcUHTfKcqsomUtpord4t3.jpg',
