    id: '1427', slug: 'the-king', title: 'The King', title_ar: 'The King', year: 2019,
    director: 'David Michôd', director_ar: 'David Michôd',
    cast: ['Timothée Chalamet', 'Joel Edgerton', 'Sean Harris', 'Tom Glynn-Carney', 'Lily-Rose Depp', 'Thomasin McKenzie'],
