    id: '1583', slug: '22-july', title: '22 July', title_ar: '22 July', year: 2018,
    director: 'Paul Greengrass', director_ar: 'Paul Greengrass',
    cast: ['Jonas Strand Gravli', 'Anders Danielsen Lie', 'Jon Øigarden', 'Seda Witt', 'Ola G. Furuseth', 'Maria Bock'],
