    cast: ['Aldo Baglio', 'Giovanni Storti', 'Giacomo Poretti', 'Aldo Maccione', 'Antonio Catania', 'Giovanni Esposito'],
    genres: ['comedy', 'crime'],
    poster_url: 'https://image.tmdb.org/t/p/w500/t7Xb04P1uCUJ1LADWD5RfqWGyDu.jpg',
