    id: '1630', slug: 'space-sweepers', title: 'Space Sweepers', title_ar: 'سبيس سويبرز', year: 2021,
    director: 'Jo Sung-hee', director_ar: 'Jo Sung-hee',
    cast: ['Song Joong-ki', 'Kim Tae-ri', 'Yoo Hai-jin', 'Jin Sun-kyu', 'Richard Armitage', 'Kim Moo-yul'],
    genres: ['drama', 'scifi'],
    poster_url: 'https://image.tmdb.org/t/p/w500/bmemsraCG1kIthY74NjDnnLRT2Q.jpg',
