    id: '1733', slug: 'malcolm-marie', title: 'Malcolm & Marie', title_ar: 'مالكوم وماري', year: 2021,
    director: 'Sam Levinson', director_ar: 'Sam Levinson',
    cast: ['John David Washington', 'Zendaya'],
    genres: ['drama', 'romance'],
    poster_url: 'https://image.tmdb.org/t/p/w500/bdidDnAZwchN5vTenoNuhGPJTri.jpg',
