    id: '1752', slug: 'the-first-time', title: 'The First Time', title_ar: 'The First Time', year: 2012,
    director: 'Jon Kasdan', director_ar: 'Jon Kasdan',
    cast: ['Dylan O\'Brien', 'Britt Robertson', 'Craig Roberts', 'James Frecheville', 'Victoria Justice', 'Maggie Elizabeth Jones'],
    genres: ['drama', 'comedy', 'romance'],
