    id: '1762', slug: 'inland-empire', title: 'Inland Empire', title_ar: 'Inland Empire', year: 2006,
    director: 'David Lynch', director_ar: 'David Lynch',
    cast: ['Laura Dern', 'Jeremy Irons', 'Justin Theroux', 'Harry Dean Stanton', 'Karolina Gruszka', 'Peter J. Lucas'],
    genres: ['horror', 'thriller', 'drama'],
    poster_url: 'https://image.tmdb.org/t/p/w500/s5f0FbVAABEnJYKaApWORTxhiFC.jpg',
