    id: '1824', slug: 'dolemite-is-my-name', title: 'Dolemite Is My Name', title_ar: 'Dolemite Is My Name', year: 2019,
    director: 'Craig Brewer', director_ar: 'Craig Brewer',
    cast: ['Eddie Murphy', 'Wesley Snipes', 'Da\'Vine Joy Randolph', 'Keegan-Michael Key', 'Mike Epps', 'Craig Robinson'],
    genres: ['drama', 'comedy', 'history'],
    poster_url: 'https://image.tmdb.org/t/p/w500/uoAqJg7ZSmftnBGOkupU1ySZQU0.jpg',
