    id: '1888', slug: 'if', title: 'IF', title_ar: 'لو', year: 2024,
    director: 'John Krasinski', director_ar: 'John Krasinski',
    cast: ['Cailey Fleming', 'Ryan Reynolds', 'John Krasinski', 'Fiona Shaw', 'Steve Carell', 'Phoebe Waller-Bridge'],
    genres: ['comedy', 'drama'],
    poster_url: 'https://image.tmdb.org/t/p/w500/xbKFv4KF3sVYuWKllLlwWDmuZP7.jpg',
