    id: '1899', slug: 'scream-vi', title: 'Scream VI', title_ar: 'الصرخة ٦', year: 2023,
    director: 'Tyler Gillett', director_ar: 'Tyler Gillett',
    cast: ['Melissa Barrera', 'Jenna Ortega', 'Jasmin Savoy Brown', 'Mason Gooding', 'Jack Champion', 'Roger L. Jackson'],
