    id: '1939', slug: 'triangle', title: 'Triangle', title_ar: 'Triangle', year: 2009,
    director: 'Christopher Smith', director_ar: 'Christopher Smith',
    cast: ['Melissa George', 'Liam Hemsworth', 'Emma Lung', 'Rachael Carpani', 'Michael Dorman', 'Joshua McIvor'],
    genres: ['horror'],
