    id: '1940', slug: 'challengers', title: 'Challengers', title_ar: 'Challengers', year: 2024,
    director: 'Luca Guadagnino', director_ar: 'Luca Guadagnino',
    cast: ['Zendaya', 'Mike Faist', 'Josh O\'Connor', 'Darnell Appling', 'Bryan Doo', 'Shane T Harris'],
