    id: '1951', slug: 'the-war-of-the-roses', title: 'The War of the Roses', title_ar: 'The War of the Roses', year: 1989,
    director: 'Danny DeVito', director_ar: 'Danny DeVito',
    cast: ['Michael Douglas', 'Kathleen Turner', 'Danny DeVito', 'Marianne Sägebrecht', 'Sean Astin', 'Heather Fairfield'],
    genres: ['comedy', 'drama'],
    poster_url: 'https://image.tmdb.org/t/p/w500/9VWwYsuXhRImUtrJGvN6bYJB2He.jpg',
