    id: '1960', slug: 'set-it-up', title: 'Set It Up', title_ar: 'Set It Up', year: 2018,
    director: 'Claire Scanlon', director_ar: 'Claire Scanlon',
    cast: ['Zoey Deutch', 'Glen Powell', 'Lucy Liu', 'Taye Diggs', 'Joan Smalls', 'Meredith Hagner'],
    genres: ['romance', 'comedy'],
    poster_url: 'https://image.tmdb.org/t/p/w500/7omfwqiiMld9EnUps3Uk9YZLy6g.jpg',
