    id: '1995', slug: 'juror-2', title: 'Juror #2', title_ar: 'المُحلّف رقم 2', year: 2024,
    director: 'Clint Eastwood', director_ar: 'Clint Eastwood',
    cast: ['Nicholas Hoult', 'Toni Collette', 'J.K. Simmons', 'Chris Messina', 'Gabriel Basso', 'Zoey Deutch'],
    genres: ['drama', 'thriller'],
