    id: '2042', slug: 'lightyear', title: 'Lightyear', title_ar: 'باز يطير', year: 2022,
    director: 'Angus MacLane', director_ar: 'Angus MacLane',
    cast: ['Chris Evans', 'Keke Palmer', 'Peter Sohn', 'Taika Waititi', 'Dale Soules', 'James Brolin'],
