    id: '2192', slug: 'tommy-boy', title: 'Tommy Boy', title_ar: 'تومي بوي', year: 1995,
    director: 'Peter Segal', director_ar: 'Peter Segal',
    cast: ['Chris Farley', 'David Spade', 'Brian Dennehy', 'Julie Warner', 'Bo Derek', 'Rob Lowe'],
    genres: ['comedy'],
    poster_url: 'https://image.tmdb.org/t/p/w500/jeEM8v1OA9u6F5NC2lzXD04Ls1U.jpg',
