    director: 'Nahnatchka Khan', director_ar: 'Nahnatchka Khan',
    cast: ['Kiernan Shipka', 'Olivia Holt', 'Troy Leigh-Anne Johnson', 'Lochlyn Munro', 'Charlie Gillespie', 'Kelcey Mawema'],
    genres: ['horror', 'comedy', 'scifi'],
    poster_url: 'https://image.tmdb.org/t/p/w500/52YBwGJ3cJs54fpBzwnT1lnqgTo.jpg',
