    id: '2199', slug: 'army-of-thieves', title: 'Army of Thieves', title_ar: 'جيش اللصوص', year: 2021,
    director: 'Matthias Schweighöfer', director_ar: 'Matthias Schweighöfer',
    cast: ['Matthias Schweighöfer', 'Nathalie Emmanuel', 'Ruby O. Fee', 'Stuart Martin', 'Guz Khan', 'Jonathan Cohen'],
    genres: ['action', 'crime', 'comedy'],
