// Maps language filter keys to the various values used in movie data
const LANG_PATTERNS: Record<string, string[]> = {
  en: ['EN', 'English'],
  ja: ['JA', 'Japanese'],
  ko: ['KO', 'Korean'],
  ar: ['AR', 'Arabic'],
  fr: ['FR', 'French'],
  it: ['IT', 'Italian'],
  tr: ['TR', 'Turkish'],
  hi: ['HI', 'Hindi'],
  ru: ['RU', 'Russian'],
}

export function getMovies(opts?: {
  genre?: string
  featured?: boolean
  search?: string
  limit?: number
  sort?: 'rating' | 'year' | 'recent'
  decade?: string
  minRating?: number
  language?: string
}): Movie[] {
  let movies = [...MOVIES]

  if (opts?.featured) {
    movies = movies.filter((m) => m.is_featured)
  }
  if (opts?.genre && opts.genre !== 'all') {
    movies = movies.filter((m) => m.genres.includes(opts.genre as any))
  }
  if (opts?.decade && opts.decade !== 'all') {
    const start = parseInt(opts.decade)
    movies = movies.filter((m) => m.year >= start && m.year < start + 10)
  }
  if (opts?.minRating) {
    movies = movies.filter((m) => m.rating_overall >= opts.minRating!)
  }
  if (opts?.language && opts.language !== 'all') {
    const patterns = LANG_PATTERNS[opts.language] ?? [opts.language]
    movies = movies.filter((m) => patterns.some((p) => m.language.startsWith(p)))
  }
  if (opts?.search) {
    const q = opts.search.toLowerCase()
    movies = movies.filter(
      (m) =>
        m.title.toLowerCase().includes(q) ||
        m.title_ar.includes(opts.search!) ||
        m.director.toLowerCase().includes(q) ||
        m.tags.some((t) => t.includes(q))
    )
  }

  if (opts?.sort === 'rating') {
    movies.sort((a, b) => b.rating_overall - a.rating_overall)
  } else if (opts?.sort === 'year') {
    movies.sort((a, b) => b.year - a.year)
  } else if (opts?.sort === 'recent') {
    // Newest additions are appended at the end of MOVIES array
    movies.reverse()
  } else {
    movies.sort((a, b) => b.rating_overall - a.rating_overall)
  }

  if (opts?.limit) {
    movies = movies.slice(0, opts.limit)
  }

  return movies
}

export function getMovieBySlug(slug: string): Movie | undefined {
  return MOVIES.find((m) => m.slug === slug)
}

export function getAllSlugs(): string[] {
  return MOVIES.map((m) => m.slug)
}

export function getMovieOfTheDay(): Movie {
  // Changes daily — uses day-of-year as seed
  const now = new Date()
  const dayOfYear = Math.floor((now.getTime() - new Date(now.getFullYear(), 0, 0).getTime()) / 86400000)
  const index = dayOfYear % MOVIES.length
  return MOVIES[index]
}

export interface Director {
  slug: string
  name: string
  name_ar: string
  movies: Movie[]
}

export function getAllDirectors(): Director[] {
  const map = new Map<string, Director>()
  for (const movie of MOVIES) {
    const slug = movie.director.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '')
    if (!map.has(slug)) {
      map.set(slug, { slug, name: movie.director, name_ar: movie.director_ar, movies: [] })
    }
    map.get(slug)!.movies.push(movie)
  }
  return Array.from(map.values()).sort((a, b) => b.movies.length - a.movies.length)
}

export function getDirectorBySlug(slug: string): Director | undefined {
  return getAllDirectors().find((d) => d.slug === slug)
}

export function getMoviesByYear(year: number): Movie[] {
  return MOVIES.filter((m) => m.year === year).sort((a, b) => b.rating_overall - a.rating_overall)
}

export function getAvailableYears(): number[] {
  const years = [...new Set(MOVIES.map((m) => m.year))].sort((a, b) => b - a)
  return years
}

export function getMovieDescription(movie: Movie, locale: string): string {
  const map: Record<string, keyof Movie> = {
    ar: 'description_ar',
    en: 'description_en',
    fr: 'description_fr',
    es: 'description_es',
    tr: 'description_tr',
    de: 'description_de',
    ja: 'description_ja',
    pt: 'description_pt',
  }
  const key = map[locale] || 'description_en'
  return (movie[key] as string) || movie.description_en
}

export interface Actor {
  slug: string
  name: string
  movies: Movie[]
}

export function getAllActors(): Actor[] {
  const map = new Map<string, Actor>()
  for (const movie of MOVIES) {
    for (const name of movie.cast) {
      if (!name) continue
      const slug = name.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '')
      if (!map.has(slug)) {
        map.set(slug, { slug, name, movies: [] })
      }
      map.get(slug)!.movies.push(movie)
    }
  }
  return Array.from(map.values())
    .filter((a) => a.movies.length >= 2)
    .sort((a, b) => b.movies.length - a.movies.length)
}

export function getActorBySlug(slug: string): Actor | undefined {
  return getAllActors().find((a) => a.slug === slug)
}
